import * as react_jsx_runtime from 'react/jsx-runtime';
import { DevSpendApprovalTarget } from '@privy-io/js-sdk-core';
export { DevSpendApprovalTarget, EvmDevSpendApprovalTarget, SvmDevSpendApprovalTarget } from '@privy-io/js-sdk-core';
import { IntegrationEnvironment, CardIssuingCardsResponse } from '@privy-io/api-types';

/**
 * Props for {@link CardSummaryView}.
 *
 * @experimental This interface may change in a minor version.
 */
type CardSummaryViewProps = {
    cardId: string;
    /**
     * Required, with no default: a card is scoped by app, user, and environment, so a caller that
     * guesses gets a 404 rather than a wrong card.
     */
    environment: 'sandbox' | 'production';
    /**
     * Height of the transactions scroll viewport, not of this whole view. Forwarded to the list,
     * which bounds itself at `24rem` otherwise.
     */
    maxTxListHeight?: string;
    /** Closes the whole panel from the header's X, on both the summary and detail views. */
    onClose?: () => void;
    /**
     * Fired after a replacement succeeds, with the id of the freshly issued card. The in-view card is
     * now closed (a "card cancelled" banner shows in its place), so a consumer can use this to close
     * this panel and open a new one scoped to the replacement.
     */
    onReplaced?: (newCardId: string) => void;
};
/**
 * A card's balance and its activity, in two sections, fed from the Privy API by `cardId`.
 *
 * @experimental This interface may change in a minor version.
 */
declare const CardSummaryView: ({ cardId, environment, maxTxListHeight, onClose, onReplaced, }: CardSummaryViewProps) => react_jsx_runtime.JSX.Element;

/**
 * Mounts the card sign-up view controlled by `useSignUpForCard`. Render this once beneath
 * `PrivyProvider`; it renders nothing until `signUp` supplies the flow options.
 *
 * @experimental This interface may change in a minor version.
 */
declare const SignUpForCardView: () => react_jsx_runtime.JSX.Element | null;

type SignUpForCardBaseOptions = {
    /** Wallet the card is created for. */
    walletId: string;
    /** CAIP-2 chain id the card funds from, e.g. `'eip155:84532'`. */
    chainId: string;
    /**
     * Asset sent on card creation, e.g. `'usdc'`, `'pathusd'`, or `'ousd'`.
     * Also used as the approval-step display name.
     */
    asset: string;
};
/**
 * Options for the card sign-up flow.
 *
 * @experimental This interface may change in a minor version.
 */
type SignUpForCardOptions = SignUpForCardBaseOptions & ({
    /**
     * Onboard against the app's sandbox card ledger. The spend approval uses the built-in
     * testnet or devnet target for `chainId`.
     */
    environment: 'sandbox';
} | {
    /** Onboard against the app's production card ledger. */
    environment: 'production';
    /**
     * On-chain spend-approval target for `chainId`. Production has no built-in target to fall
     * back on, so omitting this is a compile error. A card that spends from an Earn vault
     * ignores it and approves the vault's share token instead.
     */
    spendApproval: DevSpendApprovalTarget;
});
/**
 * Successful card sign-up result.
 *
 * @experimental This interface may change in a minor version.
 */
type SignUpForCardResult = {
    id: string;
};

/**
 * Return type for {@link useSignUpForCard}.
 *
 * @experimental This interface may change in a minor version.
 */
type UseSignUpForCardResult = {
    /** Opens card sign-up. Returns the created card ID or rejects when sign-up does not complete. */
    signUp: (opts: SignUpForCardOptions) => Promise<SignUpForCardResult>;
    /** Closes an in-progress sign-up and settles the pending `signUp` promise. */
    close: () => void;
    /**
     * Whether sign-up is in progress. Drive the container that mounts `SignUpForCardView` from this
     * instead of mirroring open state locally.
     */
    isOpen: boolean;
};
/**
 * Opens the card sign-up flow and returns its result.
 *
 * @experimental This interface may change in a minor version.
 */
declare const useSignUpForCard: () => UseSignUpForCardResult;

/**
 * Return type for {@link useGetCardsForUser}.
 *
 * @experimental This interface may change in a minor version.
 */
interface UseGetCardsForUserInterface {
    /** Returns one page of the authenticated user's cards. */
    getCardsForUser: (opts: {
        environment: IntegrationEnvironment;
        limit?: number;
        cursor?: string;
    }) => Promise<CardIssuingCardsResponse>;
}
/**
 * Returns a method for fetching the authenticated user's cards.
 *
 * @experimental This interface may change in a minor version.
 */
declare const useGetCardsForUser: () => UseGetCardsForUserInterface;

export { CardSummaryView, SignUpForCardView, useGetCardsForUser, useSignUpForCard };
export type { CardSummaryViewProps, SignUpForCardOptions, SignUpForCardResult, UseGetCardsForUserInterface, UseSignUpForCardResult };
